import os,re,json,numpy as np
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def f(A):
    A=np.array(A); H,W=A.shape
    hl=[]; vl=[]
    for r in range(H):
        nz=[int(v) for v in A[r]]
        if all(v!=0 for v in nz): hl.append((r,int(max(nz,key=nz.count))))
    for c in range(W):
        nz=[int(A[r,c]) for r in range(H)]
        if all(v!=0 for v in nz): vl.append((c,int(max(nz,key=nz.count))))
    oh=2*len(hl)+1; ow=2*len(vl)+1
    o=np.zeros((oh,ow),dtype=int)
    for i,(rv,v) in enumerate(hl): o[2*i+1,:]=v
    for j,(cv,u) in enumerate(vl): o[:,2*j+1]=u
    for i,(rv,v) in enumerate(hl):
        for j,(cv,u) in enumerate(vl):
            o[2*i+1,2*j+1]=A[rv,cv]
    return o.tolist()
for k in [1,2,3,4]:
    print(k, f(np.array(G[f'Demo pair {k} input']))==G[f'Demo pair {k} output'])
print(json.dumps(f(np.array(G['Test input']))))
